import React from 'react';

const getCategoryIcon = (category) => {
    const icons = {
        GPU: '🎮',
        CPU: '⚙️',
        SSD: '💾',
        RAM: '🧠'
    };
    return icons[category] || '📦';
};

const getCategoryColor = (category) => {
    const colors = {
        GPU: 'linear-gradient(145deg, #FF6B6B, #EE5A5A)',
        CPU: 'linear-gradient(145deg, #4FACFE, #00B4DB)',
        SSD: 'linear-gradient(145deg, #43E97B, #38F9D7)',
        RAM: 'linear-gradient(145deg, #FA709A, #FEE140)'
    };
    return colors[category] || 'var(--gradient-primary)';
};

const getStockStatus = (stock) => {
    // Защита от undefined
    const stockValue = stock || 0;
    if (stockValue === 0) return { class: 'out', text: 'Нет в наличии' };
    if (stockValue < 5) return { class: 'low', text: `Осталось ${stockValue} шт.` };
    return { class: 'in', text: `В наличии ${stockValue} шт.` };
};

const ProductCard = ({ product, onEdit, onDelete }) => {
    // Защита от undefined продукта
    if (!product) return null;

    const stockStatus = getStockStatus(product.stock);
    const categoryColor = getCategoryColor(product.category);
    const categoryIcon = getCategoryIcon(product.category);

    return (
        <div className="product-card">
            <div className="product-card__header">
                <span 
                    className="product-card__category"
                    style={{ background: categoryColor }}
                >
                    {categoryIcon} {product.category || 'Other'}
                </span>
                <span className="product-card__id">
                    #{product.id ? product.id.slice(0, 8) : 'N/A'}
                </span>
            </div>
            
            <div className="product-card__image">
                {categoryIcon}
            </div>
            
            <div className="product-card__content">
                <h3 className="product-card__title">{product.title || 'Без названия'}</h3>
                <p className="product-card__description">
                    {product.description || 'Нет описания'}
                </p>
                
                {product.specs && Object.keys(product.specs).length > 0 && (
                    <div className="product-card__specs">
                        {Object.entries(product.specs).map(([key, value]) => (
                            <div key={key}>
                                <span>{key}:</span>
                                <span>{value}</span>
                            </div>
                        ))}
                    </div>
                )}
                
                {product.rating > 0 && (
                    <div className="product-card__rating">
                        {'⭐'.repeat(Math.floor(product.rating))}
                        <span>({product.rating.toFixed(1)})</span>
                    </div>
                )}
                
                <div className="product-card__footer">
                    <span className="product-card__price">
                        {product.price ? product.price.toLocaleString() : '0'} ₽
                    </span>
                    <span className={`product-card__stock product-card__stock--${stockStatus.class}`}>
                        {stockStatus.text}
                    </span>
                </div>
                
                <div className="product-card__actions">
                    <button className="edit" onClick={() => onEdit(product)}>
                        <span>✏️</span> Редактировать
                    </button>
                    <button className="delete" onClick={() => onDelete(product.id)}>
                        <span>🗑️</span> Удалить
                    </button>
                </div>
            </div>
        </div>
    );
};

export default ProductCard;
